// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import {
    signIn,
    createPolicy,
    addCollectionPermission,
    openFieldPermissions,
    selectReadableField,
    savePolicy,
    openPolicy,
} from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8055");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(1138000);

    const pageErrors: string[] = [];
    page.on('pageerror', (error) => pageErrors.push(error.message));

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    const policyName = `TB Field Perms Policy ${Date.now()}`;

    await page.goto(baseUrl);

    const loginResponse = await signIn(page, "admin@example.com", "admin");
    expect(loginResponse.status()).toBe(200);

    await page.goto(`${baseUrl}/admin/settings/policies/+`);
    // Wait for network activities to finish
    await page.waitForTimeout(3000);

    const createResponse = await createPolicy(page, policyName);
    expect(createResponse.status()).toBe(200);

    await addCollectionPermission(page, "directus_users");
    await openFieldPermissions(page, "Read");

    // The field selector lists every directus_users field, all unselected on a new permission.
    await expect(page.getByRole("checkbox", { name: /^check_box / })).toHaveCount(0);

    await selectReadableField(page, "check_box_outline_blank Email");

    const saveResponse = await savePolicy(page);
    expect(saveResponse.status()).toBe(200);

    // Reopen the saved policy and confirm the field selection round-tripped.
    await openPolicy(page, policyName);
    await openFieldPermissions(page, "Read");

    await expect(page.getByRole("heading", { level: 1 }).filter({ hasText: "directus_users" }))
        .toHaveText(`${policyName} -> directus_users -> Read`);
    await expect(page.getByText(`Fields the ${policyName} Policy can read.`))
        .toHaveText(`Fields the ${policyName} Policy can read.`);

    // Exactly one field is readable, and it is Email — Password stays unselected.
    await expect(page.getByRole("checkbox", { name: /^check_box / })).toHaveCount(1);
    await expect(page.getByRole("checkbox", { name: "check_box Email", exact: true })).toHaveCount(1);
    await expect(page.getByRole("checkbox", { name: "check_box_outline_blank Password", exact: true })).toHaveCount(1);

    expect(pageErrors).toHaveLength(0);
});
